namespace Bazaar.CompanyIdentity;

/// <summary>
/// Writes a company build's server identity as source (doc 37 section 4a). The generated file replaces the unset placeholder
/// <c>CompanyBuildIdentity.cs</c> in the client build's copy of Bazaar.Client.Core, so each build is bound to its server.
/// Generation is pure text: nothing is compiled or executed here.
/// </summary>
public static class CompanyBuildIdentityGenerator
{
    /// <summary>Renders the complete C# source for the identity.</summary>
    public static string RenderSource(CompanyServerIdentity identity)
    {
        ArgumentNullException.ThrowIfNull(identity);
        var address = EscapeLiteral(identity.Address.AbsoluteUri);
        var pin = EscapeLiteral(identity.KeyHashPin);
        var update = identity.Update;
        // Same members as the placeholder, so the updater compiles against either; an identity without update trust renders nulls.
        var fingerprint = update is null ? "null" : $"\"{EscapeLiteral(update.UpdateSigningKeyFingerprint)}\"";
        var publicKey = update is null ? "null" : $"\"{EscapeLiteral(update.UpdateSigningPublicKey)}\"";
        var manifestUrl = update is null ? "null" : $"new Uri(\"{EscapeLiteral(update.ReleaseManifestUrl.AbsoluteUri)}\")";
        var owner = update is { IsOwnerInstall: true } ? "true" : "false";
        return $$"""
            // <auto-generated>
            // Generated by the company server for this build (doc 37 section 4a). Do not edit.
            // </auto-generated>
            #nullable enable
            namespace Bazaar.CompanyIdentity;

            /// <summary>The company server this client build was made for. Generated; the unset placeholder is replaced by it.</summary>
            public static class CompanyBuildIdentity
            {
                /// <summary>The server's base address.</summary>
                public static Uri? Address => new Uri("{{address}}");

                /// <summary>The SHA-256 pin of the server's key.</summary>
                public static string? KeyHashPin => "{{pin}}";

                /// <summary>Lowercase hex fingerprint of the update signing key, or null when this build carries no update trust.</summary>
                public static string? UpdateSigningKeyFingerprint => {{fingerprint}};

                /// <summary>The ASCII-armoured OpenPGP public key text for release manifests, or null when this build carries no update trust.</summary>
                public static string? UpdateSigningPublicKey => {{publicKey}};

                /// <summary>True only for the owner's own build (allows the Latest-Commit channel).</summary>
                public static bool IsOwnerInstall => {{owner}};

                /// <summary>The release manifest address on the company server's origin, or null when this build carries no update trust.</summary>
                public static Uri? ReleaseManifestUrl => {{manifestUrl}};
            }

            """;
    }

    /// <summary>Writes the generated source to <c>CompanyBuildIdentity.cs</c> in <paramref name="projectDirectory"/>, replacing the placeholder.</summary>
    /// <returns>The full path written.</returns>
    public static string WriteSource(CompanyServerIdentity identity, string projectDirectory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(projectDirectory);
        var path = Path.Combine(projectDirectory, "CompanyBuildIdentity.cs");
        var directory = Path.GetDirectoryName(path)!;
        Directory.CreateDirectory(directory);
        File.WriteAllText(path, RenderSource(identity), new System.Text.UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
        return path;
    }

    /// <summary>The file name <see cref="WriteUpdateSigningKey"/> writes.</summary>
    public const string UpdateSigningKeyFileName = "UpdateSigningPublicKey.asc";

    /// <summary>Writes the armoured update signing public key to <c>UpdateSigningPublicKey.asc</c> in <paramref name="directory"/>.</summary>
    /// <returns>The full path written.</returns>
    /// <exception cref="InvalidOperationException">The identity carries no update trust.</exception>
    public static string WriteUpdateSigningKey(CompanyServerIdentity identity, string directory)
    {
        ArgumentNullException.ThrowIfNull(identity);
        ArgumentException.ThrowIfNullOrWhiteSpace(directory);
        var update = identity.Update ?? throw new InvalidOperationException("This identity carries no update trust.");
        Directory.CreateDirectory(directory);
        var path = Path.Combine(directory, UpdateSigningKeyFileName);
        File.WriteAllText(path, update.UpdateSigningPublicKey + "\n", new System.Text.UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
        return path;
    }

    // Escapes for a regular (non-verbatim) C# string literal; line breaks in armoured keys become escapes.
    private static string EscapeLiteral(string value) =>
        value.Replace("\\", "\\\\", StringComparison.Ordinal)
            .Replace("\"", "\\\"", StringComparison.Ordinal)
            .Replace("\r", "\\r", StringComparison.Ordinal)
            .Replace("\n", "\\n", StringComparison.Ordinal)
            .Replace("\t", "\\t", StringComparison.Ordinal);
}
